     keys['KeyQ']=false; wheelRelease(); return true;
   }
   function shoots(sec){ var a0=p.ammo; p.lastShot=-1e9; p.fired=false; run(sec,true); return p.ammo<a0; }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
